CREATE TABLE leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, first_name text NOT NULL, last_name text DEFAULT '', phone_number text DEFAULT '', instagram_handle text DEFAULT '', source text NOT NULL DEFAULT 'Referral', status text NOT NULL DEFAULT 'New', health_goals text DEFAULT '', pain_points text DEFAULT '', ai_score integer NOT NULL DEFAULT 0, last_contacted_at timestamptz, next_follow_up_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());